import React, { useState, useEffect } from 'react';
import { useTrackerData } from './hooks/useTrackerData';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import CalendarView from './components/CalendarView';
import Reports from './components/Reports';
import RewardsPanel from './components/RewardsPanel';
import NightReview from './components/NightReview';
import { Bell, Download, ShieldCheck, Sun, Moon, Info } from 'lucide-react';

const App: React.FC = () => {
  const {
    currentDay,
    calendarData,
    points,
    streak,
    badges,
    darkMode,
    notificationsEnabled,
    setDarkMode,
    setNotificationsEnabled,
    toggleTask,
    skipTask,
    completeDay,
    currentDayData
  } = useTrackerData();

  const [currentView, setCurrentView] = useState('dashboard');
  const [showNightReviewModal, setShowNightReviewModal] = useState(false);

  // Auto-trigger Night Review reminder after 9 PM
  useEffect(() => {
    const checkTime = () => {
      const now = new Date();
      const hours = now.getHours();

      // If after 9 PM and current day is not yet completed
      if (hours >= 21 && currentDayData && !currentDayData.completed && !showNightReviewModal) {
         // Optionally show a notification or auto-open
         // For now, we'll just rely on the user clicking the button or a persistent banner
      }
    };

    const timer = setInterval(checkTime, 60000);
    return () => clearInterval(timer);
  }, [currentDayData, showNightReviewModal]);

  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(calendarData));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `180day_tracker_export_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const renderView = () => {
    switch (currentView) {
      case 'dashboard':
        return currentDayData ? (
          <Dashboard 
            dayData={currentDayData} 
            toggleTask={toggleTask} 
            skipTask={skipTask}
            currentDay={currentDay}
          />
        ) : null;
      case 'calendar':
        return <CalendarView 
          calendarData={calendarData} 
          currentDay={currentDay}
          onSelectDay={(day) => {
             // Logic to view history of a specific day
             console.log("Viewing day:", day);
             // We can expand this to show a readonly dashboard for past days
          }}
        />;
      case 'reports':
        return <Reports calendarData={calendarData} onExport={handleExport} />;
      case 'rewards':
        return <RewardsPanel points={points} streak={streak} unlockedBadges={badges} />;
      case 'settings':
        return (
          <div className="p-8 max-w-4xl mx-auto space-y-8 animate-fade-in">
             <div className="space-y-1">
               <h2 className="text-sm font-bold tracking-widest text-slate-500 uppercase">Configuration</h2>
               <h1 className="text-4xl font-bold tracking-tight text-white font-black">App Settings</h1>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="glass-card p-6 space-y-6">
                   <h3 className="text-lg font-bold flex items-center gap-2">
                     <ShieldCheck size={20} className="text-blue-400" /> System Controls
                   </h3>
                   <div className="space-y-4">
                     <div className="flex items-center justify-between p-4 bg-white/5 rounded-2xl">
                        <div>
                          <p className="text-sm font-bold text-white">Visual Mode</p>
                          <p className="text-[10px] text-slate-500 uppercase font-black">Switch Theme Styling</p>
                        </div>
                        <button 
                          onClick={() => setDarkMode(!darkMode)}
                          className="p-2 rounded-xl bg-white/5 text-slate-400 hover:text-white"
                        >
                          {darkMode ? <Moon size={20} /> : <Sun size={20} />}
                        </button>
                     </div>
                     <div className="flex items-center justify-between p-4 bg-white/5 rounded-2xl">
                        <div>
                          <p className="text-sm font-bold text-white">Browser Notifications</p>
                          <p className="text-[10px] text-slate-500 uppercase font-black">Alerts at 6AM, 9PM, 11PM</p>
                        </div>
                        <button 
                          onClick={() => {
                            if (!notificationsEnabled) {
                              Notification.requestPermission().then(res => {
                                if (res === 'granted') setNotificationsEnabled(true);
                              });
                            } else {
                              setNotificationsEnabled(false);
                            }
                          }}
                          className={`p-2 rounded-xl transition-all ${notificationsEnabled ? 'bg-blue-600 text-white' : 'bg-white/5 text-slate-400'}`}
                        >
                          <Bell size={20} />
                        </button>
                     </div>
                   </div>
                </div>

                <div className="glass-card p-6 space-y-6 bg-red-600/5">
                   <h3 className="text-lg font-bold flex items-center gap-2 text-red-100">
                     <Info size={20} className="text-red-400" /> Danger Zone
                   </h3>
                   <button 
                     onClick={() => {
                        if(confirm("Are you SURE? This will wipe all 180 days of progress.")) {
                          localStorage.removeItem('180dayTracker');
                          window.location.reload();
                        }
                     }}
                     className="w-full py-4 rounded-2xl bg-red-600/10 border border-red-500/20 text-red-500 font-bold text-sm hover:bg-red-600/20 transition-all uppercase tracking-widest"
                   >
                     Reset All Progress Data
                   </button>
                   <p className="text-[10px] text-slate-500 font-medium px-2">
                     Warning: This action is irreversible. All badges, points, and history will be lost forever.
                   </p>
                </div>
             </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className={`flex min-h-screen ${darkMode ? 'bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'} transition-colors duration-500`}>
      <Sidebar 
        currentView={currentView} 
        setCurrentView={setCurrentView}
        darkMode={darkMode}
        setDarkMode={setDarkMode}
        points={points}
        streak={streak}
      />

      <main className="flex-1 overflow-y-auto h-screen relative scrollbar-thin">
        {/* Floating Night Review Trigger */}
        {currentDayData && !currentDayData.completed && (
          <div className="fixed bottom-8 right-8 z-40 transition-transform hover:scale-105 active:scale-95">
             <button 
               onClick={() => setShowNightReviewModal(true)}
               className="px-6 py-4 rounded-2xl bg-gradient-to-r from-blue-600 to-purple-600 text-white font-black text-xs uppercase tracking-widest shadow-2xl shadow-blue-600/40 border border-white/10 flex items-center gap-3 group"
             >
               <Moon size={18} className="group-hover:rotate-12 transition-transform" /> 
               Submit Night Review
             </button>
          </div>
        )}

        <div className="pb-32">
          {renderView()}
        </div>
      </main>

      {/* Modals */}
      {showNightReviewModal && currentDayData && (
        <NightReview 
          dayData={currentDayData}
          onClose={() => setShowNightReviewModal(false)}
          onComplete={(note, plan) => {
            completeDay(currentDay, note, plan);
            setShowNightReviewModal(false);
          }}
        />
      )}
    </div>
  );
};

export default App;
